```javascript
import {
  PlaneGeometry,
  BoxGeometry,
  Mesh,
  Vector3,
  Color,
  MeshBasicNodeMaterial,
  MeshBasicMaterial,
} from 'three/webgpu';
import { texture, uniform } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // ---- destructure config ----
  const { textContent, scenePlacement, atlasRegion, behaviors } = config;
  const { position, rotation, scale } = scenePlacement;
  const { interactions, dataBindings, effects } = behaviors;

  // ---- constants ----
  const CARD_W = 1.6;
  const CARD_H = 1.0;
  const BORDER_WIDTH = 0.03;
  const HOVER_RISE = 0.15;
  const PRESS_SCALE = 0.97;

  // ---- groups and meshes ----
  const group = new THREE.Group();
  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  // original positions/scale for animation
  const origY = group.position.y;

  // ---- load texture ----
  const texUrl = '/prism-mock/home/nodes/floating-accent.png';
  const tex = ctx.textureLoader.load(texUrl);
  tex.colorSpace = THREE.SRGBColorSpace;

  // ---- plane mesh ----
  const planeGeo = new PlaneGeometry(CARD_W, CARD_H);
  // TSL texture node
  const texNode = texture(tex);
  const planeMat = new MeshBasicNodeMaterial({ colorNode: texNode, transparent: true });
  const planeMesh = new Mesh(planeGeo, planeMat);
  group.add(planeMesh);

  // ---- border mesh (accent edge) ----
  const borderGeo = new BoxGeometry(
    CARD_W + BORDER_WIDTH * 2,
    CARD_H + BORDER_WIDTH * 2,
    BORDER_WIDTH * 2
  );
  const borderMat = new MeshBasicMaterial({
    color: config.colors.paper, // default to paper, will change on hover
    transparent: true,
    opacity: 0.8,
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -BORDER_WIDTH; // behind plane
  group.add(borderMesh);

  // ---- MSDF text ----
  const textSize = 0.34; // headline scale from tokens
  const textMesh = ctx.fontAtlas({
    text: textContent?.headline || 'Journal 3',
    size: textSize,
    font: 'Lora',
    color: config.colors.ink,
  });
  if (textMesh) {
    textMesh.position.z = 0.001; // slightly in front
    group.add(textMesh);
  }

  // ---- gsap timelines ----
  const tlHover = gsap.timeline({ paused: true });
  const tlPress = gsap.timeline({ paused: true });

  // hover rise-in
  tlHover.to(group.position, {
    y: origY + HOVER_RISE,
    duration: 0.7,
    ease: 'power3.out',
  });
  // border accent on hover
  tlHover.to(borderMat.color, {
    r: new Color(config.colors.accent).r,
    g: new Color(config.colors.accent).g,
    b: new Color(config.colors.accent).b,
    duration: 0.3,
    ease: 'power2.out',
  }, 0);

  // press-down on click
  tlPress.to(group.scale, {
    x: PRESS_SCALE,
    y: PRESS_SCALE,
    z: PRESS_SCALE,
    duration: 0.12,
    ease: 'back.out',
  });

  // ---- event handlers (attached via userData) ----
  group.userData.handlers = {
    pointerenter: () => {
      tlHover.play();
    },
    pointerleave: () => {
      tlHover.reverse();
    },
    pointerdown: () => {
      tlPress.play();
    },
    pointerup: () => {
      tlPress.reverse();
      // emit journal.select event
      ctx.emit('hub-journal.select', { label: textContent?.headline || 'Journal 3' });
    },
  };

  // ---- cleanup ----
  group.userData.cleanup = () => {
    tlHover.kill();
    tlPress.kill();
    tex.dispose();
    planeGeo.dispose();
    planeMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    if (textMesh) {
      textMesh.geometry.dispose();
      textMesh.material.dispose();
    }
  };

  return group;
}
